<script setup>
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import UiIcon from "../../components/UiIcon.vue";
import { completePersonalTask, deletePersonalTask, getAssignment, getMySubmission, getPersonalTask, saveMySubmission } from "../../services/studentApi";

const route = useRoute(); const router = useRouter(); const loading = ref(true); const error = ref(""); const item = ref(null); const submission = ref(null); const text = ref(""); const saving = ref(false); const submitting = ref(false);
const assignmentMode = computed(() => route.params.kind === "assignment");
const itemStatus = computed(() => assignmentMode.value ? item.value?.status : item.value?.status === "completed" ? "已完成" : "待完成");
const dueState = computed(() => { if (!item.value?.deadline) return "未设置截止时间"; const value = new Date(item.value.deadline).valueOf(); return value < Date.now() && !["submitted", "graded", "completed"].includes(item.value.status) ? "已逾期" : new Date(item.value.deadline).toLocaleString("zh-CN"); });
const submissionLabel = computed(() => ({ draft: "草稿", submitted: "已提交", graded: "已评分" }[submission.value?.status] || "尚未提交"));
function dateText(value) { if (!value) return "未设置截止时间"; const d = new Date(value); return Number.isNaN(d.valueOf()) ? value : d.toLocaleString("zh-CN"); }
async function load() { loading.value = true; error.value = ""; try { if (assignmentMode.value) { item.value = await getAssignment(route.params.id); submission.value = await getMySubmission(route.params.id); text.value = submission.value?.text_content || ""; } else item.value = await getPersonalTask(route.params.id); } catch (e) { error.value = e.response?.data?.detail || "事项详情加载失败。"; } finally { loading.value = false; } }
async function saveDraft(shouldSubmit = false) { if (!text.value.trim() || saving.value || submitting.value) return; if (shouldSubmit) submitting.value = true; else saving.value = true; try { submission.value = await saveMySubmission(route.params.id, { text_content: text.value, submit: shouldSubmit }); } catch (e) { error.value = e.response?.data?.detail || "提交失败，请重试。"; } finally { saving.value = false; submitting.value = false; } }
async function togglePersonal() { try { item.value = await completePersonalTask(item.value.id, item.value.status !== "completed"); } catch (e) { error.value = e.response?.data?.detail || "更新待办状态失败。"; } }
async function removePersonal() { if (!window.confirm("确认删除这条待办吗？")) return; try { await deletePersonalTask(item.value.id); router.replace("/tasks"); } catch (e) { error.value = e.response?.data?.detail || "删除失败，请重试。"; } }
onMounted(load);
</script>

<template>
  <main class="student-page page-enter student-detail-page"><button class="back-link" @click="router.push('/tasks')"><UiIcon name="PhArrowLeft" />返回待办</button><div v-if="loading" class="student-detail-loading"><div class="student-skeleton"></div><div class="student-skeleton"></div></div><div v-else-if="error" class="student-alert error"><UiIcon name="PhWarningCircle" />{{ error }}<button class="link-button" @click="load">重试</button></div><template v-else-if="item"><section class="detail-hero-board surface task-detail-hero"><div class="detail-hero-icon" :class="assignmentMode ? 'blue' : 'warm'"><UiIcon :name="assignmentMode ? 'PhFileText' : 'PhCheckSquare'" :size="30" /></div><div><span class="status-pill" :class="assignmentMode ? 'blue' : 'warm'">{{ assignmentMode ? '课程作业' : '个人待办' }}</span><h1>{{ item.title }}</h1><p>{{ assignmentMode ? item.course_name || '课程作业' : item.source_name || '个人安排' }} · {{ itemStatus }}</p></div><span class="detail-hero-deadline" :class="dueState === '已逾期' ? 'danger' : ''"><small>截止时间</small><strong>{{ dueState }}</strong></span></section><section class="detail-two-column task-detail-columns"><article class="student-panel surface detail-reading-card"><div class="detail-kicker"><span class="eyebrow">TASK DETAILS</span><span class="toolbar-count">{{ assignmentMode ? item.class_name || '课程班级' : '我的任务' }}</span></div><h2 class="detail-section-title">事项说明</h2><p class="detail-description">{{ item.description || '暂未补充说明。' }}</p><dl class="info-grid detail-info-grid"><div><dt>截止时间</dt><dd>{{ dateText(item.deadline) }}</dd></div><div><dt>{{ assignmentMode ? '发布教师' : '来源' }}</dt><dd>{{ item.author_name || item.source_name || '—' }}</dd></div><div v-if="assignmentMode"><dt>提交方式</dt><dd>{{ (item.submission_types || []).join('、') || '在线文本' }}</dd></div><div v-else><dt>提醒</dt><dd>{{ item.reminder_minutes == null ? '未设置' : `提前 ${item.reminder_minutes} 分钟` }}</dd></div></dl><div class="detail-context-block"><span class="eyebrow">NEXT STEP</span><h3>{{ assignmentMode ? (submission?.status === 'graded' ? '查看教师反馈' : '完成并提交作业') : (item.status === 'completed' ? '这件事已经完成' : '完成后记得更新状态') }}</h3><p>{{ assignmentMode ? '先保存草稿，再确认内容无误后正式提交。' : '完成状态会同步到待办列表和首页摘要。' }}</p></div><div v-if="!assignmentMode" class="detail-actions"><button class="primary-button" @click="togglePersonal"><UiIcon name="PhCheck" />{{ item.status === 'completed' ? '标记未完成' : '标记已完成' }}</button><button class="secondary-button danger-outline" @click="removePersonal"><UiIcon name="PhTrash" />删除待办</button></div></article><aside v-if="assignmentMode" class="student-panel surface submission-panel detail-submission-card"><div class="student-panel-head"><div><span class="eyebrow">MY SUBMISSION</span><h2>我的提交</h2></div><span class="status-pill" :class="submission?.status === 'submitted' || submission?.status === 'graded' ? 'green' : 'blue'">{{ submissionLabel }}</span></div><div class="submission-state-row"><span class="submission-state-icon" :class="submission?.status === 'graded' ? 'green' : submission?.status === 'submitted' ? 'blue' : 'warm'"><UiIcon :name="submission?.status === 'graded' ? 'PhSealCheck' : submission?.status === 'submitted' ? 'PhPaperPlaneTilt' : 'PhPencilSimpleLine'" /></span><span><strong>{{ submission?.status === 'graded' ? '教师已评分' : submission?.status === 'submitted' ? '内容已提交' : '从草稿开始' }}</strong><small>{{ submission?.submitted_at ? `提交于 ${dateText(submission.submitted_at)}` : '内容只会在你主动保存后发送' }}</small></span></div><textarea v-model="text" name="assignment-submission" rows="10" :disabled="item.status === 'closed' || submission?.status === 'graded'" placeholder="写下你的作业内容，先保存草稿，再提交给教师"></textarea><div v-if="submission?.score != null" class="grade-result"><strong>{{ submission.score }} 分</strong><span>{{ submission.teacher_comment || '教师暂未留下评语。' }}</span></div><div class="submission-actions"><button class="secondary-button" :disabled="saving || !text.trim()" @click="saveDraft(false)">{{ saving ? '保存中…' : '保存草稿' }}</button><button class="primary-button" :disabled="submitting || !text.trim() || item.status === 'closed' || submission?.status === 'graded'" @click="saveDraft(true)">{{ submitting ? '提交中…' : submission?.status === 'submitted' ? '重新提交' : '正式提交' }}</button></div><p class="submission-hint"><UiIcon name="PhInfo" />提交前请确认内容完整，正式提交后状态由教师端返回。</p></aside><aside v-else class="student-panel surface task-action-card"><span class="tool-summary-icon warm"><UiIcon name="PhCheckSquare" /></span><span class="eyebrow">PERSONAL TASK</span><h2>把它放回你的节奏</h2><p>完成、恢复或删除操作都会直接同步到个人待办数据。</p><div class="task-action-summary"><span><small>当前状态</small><strong>{{ itemStatus }}</strong></span><span><small>截止时间</small><strong>{{ dueState }}</strong></span></div></aside></section></template></main>
</template>
